/* Saved comparison: explore the direction of a change. */
.circuit-active-root .circuit-observation-order{display:flex;align-items:center;gap:10px 16px;flex-wrap:wrap;min-width:0;margin:16px 0 22px;padding:12px;border:1px solid #648994;border-radius:12px;background:#142e3d}
.circuit-active-root .circuit-observation-order>p{flex:1 1 15em;min-width:0;margin:0;color:#d1e3e9;font-size:13px;line-height:1.7;overflow-wrap:anywhere}
.circuit-active-root .circuit-observation-swap{display:inline-flex;align-items:center;justify-content:center;gap:8px;box-sizing:border-box;min-height:44px;min-width:44px;max-width:100%;padding:10px 14px;border:1px solid #a3c8dc;border-radius:9px;background:#23455b;color:#edf6fc;font-size:14px;font-weight:650;line-height:1.6;white-space:normal;overflow-wrap:anywhere;cursor:pointer}
.circuit-active-root .circuit-observation-swap svg{flex:0 0 20px}
.circuit-active-root .circuit-observation-swap:hover:not(:disabled){background:#305972;border-color:#d1e8f4}
.circuit-active-root .circuit-observation-swap:focus-visible{outline:2px solid #ffd780;outline-offset:3px}
.circuit-active-root .circuit-observation-swap:disabled{background:#243943;border-color:#75919e;color:#c3d2d9;cursor:default}
.circuit-active-root .circuit-observation-order-announcement{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.circuit-active-root .circuit-observation-comparison .circuit-observation-delta dd{display:flex;flex-direction:column;align-items:flex-end;gap:5px}
.circuit-active-root .circuit-observation-delta-direction{display:block;max-width:100%;padding:2px 7px;border:1px solid #849da6;border-radius:6px;background:#263b45;color:#dfebee;font-size:12px;font-weight:600;line-height:1.6;white-space:normal;overflow-wrap:anywhere}
.circuit-active-root .circuit-observation-delta-direction[data-change-direction="increase"]{background:#183e49;border-color:#80b7c5;color:#d3f3f7}
.circuit-active-root .circuit-observation-delta-direction[data-change-direction="decrease"]{background:#33374f;border-color:#acaecf;color:#e6e7fb}
@media(max-width:640px){.circuit-active-root .circuit-observation-swap{width:100%}}
@media(forced-colors:active){.circuit-active-root .circuit-observation-order{background:Canvas;border-color:CanvasText}.circuit-active-root .circuit-observation-order>p{color:CanvasText}.circuit-active-root .circuit-observation-swap{background:ButtonFace;border-color:ButtonText;color:ButtonText}.circuit-active-root .circuit-observation-swap:disabled{border-color:GrayText;color:GrayText}.circuit-active-root .circuit-observation-swap:focus-visible{outline-color:Highlight}.circuit-active-root .circuit-observation-delta-direction[data-change-direction]{background:Canvas;border-color:CanvasText;color:CanvasText}}
